python3 << 'PYEOF'
import requests, json

# Search BioContainers for R base
url = "https://quay.io/api/v1/repository/biocontainers/r-base/tag"
params = {"limit": 20, "onlyActiveTags": "true", "page": 1}
r = requests.get(url, params=params)
if r.status_code == 200:
    data = r.json()
    for tag in data.get('tags', [])[:15]:
        print(f"{tag['name']} (modified: {tag.get('last_modified', '?')})")
else:
    print(f"Status: {r.status_code}")
PYEOF

